sql.where:
gt.deleted = 0

    AND gt.name LIKE CONCAT('%', #{reqVO.name}, '%')


    AND gt.location LIKE CONCAT('%', #{reqVO.location}, '%')


    AND gt.area_code = #{reqVO.areaCode}


    AND gt.operation_status_id = #{reqVO.operationStatusId}


    AND gt.manager_id = #{reqVO.managerId}


    AND gt.daily_transfer_volume = #{reqVO.dailyTransferVolume}


    AND gt.equipment_rate = #{reqVO.equipmentRate}


    AND gt.environment_rate = #{reqVO.environmentRate}


    AND gt.unhandled_alarm_count = #{reqVO.unhandledAlarmCount}


    AND gt.pending_maintenance_count = #{reqVO.pendingMaintenanceCount}


    AND gt.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}
